// order-message.js: imports the domain, imported by neither shape's owner
export const toMessage = (order) => ({
  id: order.id,
  customer_id: order.customer.id,          // reference -> stable id
  total_minor: order.total.minorUnits,
});
export const fromMessage = (m) =>
  Order.rehydrate(m.id, m.customer_id, Money.minor(m.total_minor));  // absent -> explicit
